def process(load_conflicts) -> pd.DataFrame:
    df = load_conflicts.copy()
    # Filter: StartYear >= 800, EndYear <= 1400, duration >= 1 year (EndYear - StartYear >= 1)
    filtered = df[
        (df['StartYear'] >= 800) &
        (df['StartYear'] <= 1400) &
        (df['EndYear'] - df['StartYear'] >= 1)
    ]
    return filtered.reset_index(drop=True)
